let res;
try {
  res = typeof $json.output === 'string' ? JSON.parse($json.output) : ($json.output || $json);
} catch (e) {
  res = {
    status: 'eskalasi_cs',
    jawaban: typeof $json.output === 'string' ? $json.output : 'Format respons tidak valid',
    data_dipakai: [],
    confidence: 0,
    alasan: 'Gagal mem-parsing output JSON agent'
  };
}

return [{
  json: {
    status: res.status || 'eskalasi_cs',
    jawaban: res.jawaban || '',
    data_dipakai: Array.isArray(res.data_dipakai) ? res.data_dipakai : [],
    confidence: typeof res.confidence === 'number' ? res.confidence : 0,
    alasan: res.alasan || ''
  }
}];

